import { Group, Mesh, PlaneGeometry, Color, PointLight, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec2, texture, sin, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: G } = ctx.THREE ?? {};
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const inkColor = new Color(inkHex);
  const surfaceColor = new Color(surfaceHex);
  const accentColor = new Color(accentHex);

  const root = new Group();
  const inner = new Group();
  root.add(inner);

  // --- label plate ---
  const width = 1.3;
  const height = 0.42;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  const gradientTint = mix(
    vec3(inkColor.r, inkColor.g, inkColor.b),
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    uv().y
  );

  const grainRaw = fract(
    sin(dot(uv().mul(937.12), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainSigned = grainRaw.sub(0.5).mul(0.05);
  const grainVec = vec3(grainSigned, grainSigned, grainSigned);

  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
  });
  material.transparent = true;
  material.opacity = 0;
  material.colorNode = gradientTint.add(grainVec);

  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  inner.add(plane);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      const texNode = texture(tex);
      const tintedTex = texNode.rgb.mul(
        mix(vec3(1, 1, 1), gradientTint, 0.4)
      );
      material.colorNode = tintedTex.add(grainVec);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // --- accent underline ---
  const accentGeometry = new PlaneGeometry(0.7, 0.025, 1, 1);
  const accentMaterial = new MeshStandardNodeMaterial({
    roughness: 0.4,
    metalness: 0.1,
  });
  accentMaterial.transparent = true;
  accentMaterial.opacity = 0;
  accentMaterial.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  accentMaterial.emissiveNode = vec3(accentColor.r, accentColor.g, accentColor.b).mul(0.6);
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(0, -height * 0.32, 0.015);
  inner.add(accentBar);

  // --- rim light for the metal to catch ---
  const rimLight = new PointLight(new Color(paperHex), 0.7, 3.0);
  rimLight.position.set(0.6, 0.35, 0.9);
  inner.add(rimLight);

  // --- text: "Collection 2" ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((t) => t.role === 'headline') ?? { text: 'Collection 2', typography: { fontSize: 39 } };
  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Collection 2', {
    fontSize: headlineItem.typography?.fontSize ?? 39,
    color: paperHex,
    align: 'center',
  });
  headline.position.set(0, height * 0.06, 0.02);
  inner.add(headline);

  // --- motion: weighted settle + rise-in, static idle ---
  inner.scale.set(1.04, 1.04, 1.04);
  inner.position.y = -0.03;

  const tl = gsap.timeline();
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(material, { opacity: 1, duration: 0.7, ease: 'power2.out' }, 0);
  tl.to(accentMaterial, { opacity: 1, duration: 0.7, ease: 'power2.out' }, 0.05);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    accentGeometry.dispose();
    accentMaterial.dispose();
    if (loadedTexture) loadedTexture.dispose();
    if (headline.geometry) headline.geometry.dispose();
    if (headline.material) {
      if (Array.isArray(headline.material)) {
        headline.material.forEach((m) => m.dispose());
      } else {
        headline.material.dispose();
      }
    }
    inner.remove(rimLight);
    root.clear();
  };

  return root;
}
